INSERT INTO documents (title, description, document_url, document_type, category, language) VALUES
('Energy Efficiency and Conservation Loan Program', 'https://www.rd.usda.gov/programs-services/electric-programs/energy-efficiency-and-conservation-loan-program', 'The Energy Efficiency and Conservation Loan Program (EECLP) provides loans to finance energy efficiency and conservation projects for commercial, industrial, and residential consumers. With the EECLP, eligible utilities, including existing Rural Utilities Service borrowers can borrow money tied to Treasury rates of interest and re-lend the money to develop new and diverse energy service products within their service territories.', 'Programs & Services', 'General', 'en'),
('Energy Resource Conservation', 'https://www.rd.usda.gov/programs-services/electric-programs/energy-resource-conservation', 'The Energy Resource Conservation (ERC) Program enables current Rural Utilities Service (RUS) borrowers to make funds available to their consumers for energy conservation and renewable energy projects by deferring payment of principal and interest.', 'Programs & Services', 'General', 'en'),
('High Energy Cost Grants', 'https://www.rd.usda.gov/programs-services/electric-programs/high-energy-cost-grants', 'This program assists energy providers and other eligible entities in lowering energy costs for families and individuals in areas with extremely high per-household energy costs (275 percent of the national average or higher.)', 'Programs & Services', 'General', 'en'),
('Rural Energy Savings Program', 'https://www.rd.usda.gov/programs-services/electric-programs/rural-energy-savings-program', 'The Rural Energy Savings Program (RESP) provides loans to rural utilities and other companies who provide energy efficiency loans to qualified consumers to implement durable cost-effective energy efficiency measures.', 'Programs & Services', 'General', 'en'),
('State Bulk Fuel Revolving Loan Fund', 'https://www.rd.usda.gov/programs-services/electric-programs/state-bulk-fuel-revolving-loan-fund', 'This program helps State governments establish and support revolving loan funds to provide a more cost-effective means of purchasing fuel for remote communities that are not served by surface transportation (highways, transit systems, railways, and waterways) year round.', 'Programs & Services', 'General', 'en'),
('Rural Energy for America Program Energy Audits & Renewable Energy Development Assistance Grants (REAP EA/REDA)', 'https://www.rd.usda.gov/programs-services/energy-programs/rural-energy-america-program-energy-audit-renewable-energy-development-assistance-grants', 'This program assists rural small businesses and agricultural producers by conducting and promoting energy audits and providing Renewable Energy Development Assistance (REDA).', 'Programs & Services', 'General', 'en'),
('Rural Energy for America Program Renewable Energy Systems & Energy Efficiency Improvement Loans & Grants (REAP RES/EEI)', 'https://www.rd.usda.gov/programs-services/energy-programs/rural-energy-america-program-renewable-energy-systems-energy-efficiency-improvement-guaranteed-loans', 'This program provides guaranteed loan financing and grant funding to agricultural producers and rural small businesses for renewable energy systems or to make energy efficiency improvements.', 'Programs & Services', 'General', 'en'),
('Rural Energy for America Program Technical Assistance Grant (REAP TAG)', 'https://www.rd.usda.gov/programs-services/energy-programs/rural-energy-america-technical-assistance-grant-program', 'These grant funds will be made to qualified type of Applicants to provide technical assistance to Agricultural Producers and Rural Small Businesses applying to REAP.', 'Programs & Services', 'General', 'en'),
('Biorefinery, Renewable Chemical, and Biobased Product Manufacturing Assistance Program (9003)', 'https://www.rd.usda.gov/programs-services/energy-programs/biorefinery-renewable-chemical-and-biobased-product-manufacturing-assistance-program', 'This program provides loan guarantees up to $250 million to assist in the development, construction and retrofitting of new and emerging technologies. These technologies are: advanced biofuels, renewable chemicals and biobased products.', 'Programs & Services', 'General', 'en'),
('Advanced Biofuel Payment Program (9005)', 'https://www.rd.usda.gov/programs-services/energy-programs/advanced-biofuel-payment-program', 'This program’s goal is to increase the production of advanced biofuels.', 'Programs & Services', 'General', 'en'),
('Biobased Markets and Development Access Grant Program', 'https://www.rd.usda.gov/programs-services/energy-programs/biobased-markets-and-development-access-grant-program', 'The Biobased Markets and Development Access Grants Program (BDAP) provides grants to eligible applicants to establish and validate the commercial viability of certain biobased technologies by building or operating integrated demonstration units (IDUs)– facilities that demonstrate continuous, successful production for a set period of time.', 'Programs & Services', 'General', 'en'),
('Higher Blends Infrastructure Incentive Program (HBIIP)', 'https://www.rd.usda.gov/programs-services/energy-programs/higher-blends-infrastructure-incentive-program', 'The purpose of the HBIIP is to increase significantly the sales and use of higher blends of ethanol and biodiesel by expanding the infrastructure for renewable fuels derived from U.S. agricultural products. The program is also intended to encourage a more comprehensive approach to market higher blends by sharing the costs related to building out biofuel-related infrastructure.', 'Programs & Services', 'General', 'en'),
('BioPreferred Program', 'https://www.biopreferred.gov/BioPreferred/', 'BioPreferred Program is to increase the purchase and use of biobased products.', 'Programs & Services', 'General', 'en'),
('Rural Energy Pilot Program (REPP)', 'https://www.rd.usda.gov/programs-services/energy-programs/rural-energy-pilot-program', 'The Rural Energy Pilot Program (REPP) grant offers financial assistance for rural communities to further develop renewable energy.', 'Programs & Services', 'General', 'en'),
('Directives', 'https://www.rd.usda.gov/resources/directives', '[object Object]', 'Programs & Services', 'General', 'en'),
('Disaster Assistance', 'https://www.rd.usda.gov/resources/rural-development-disaster-assistance', '[object Object]', 'Programs & Services', 'General', 'en'),
('Environmental Studies', 'https://www.rd.usda.gov/resources/environmental-studies', '[object Object]', 'Programs & Services', 'General', 'en'),
('Forms', 'https://www.rd.usda.gov/resources/forms', '[object Object]', 'Programs & Services', 'General', 'en'),
('Publications', 'https://www.rd.usda.gov/resources/publications', '[object Object]', 'Programs & Services', 'General', 'en'),
('Regulations and Guidance', 'https://www.rd.usda.gov/resources/regulations-and-guidance', '[object Object]', 'Programs & Services', 'General', 'en'),
('Guaranteed Underwriting System (GUS)', 'https://www.rd.usda.gov/resources/usda-linc-training-resource-library/guaranteed-underwriting-system', '[object Object]', 'Programs & Services', 'General', 'en'),
('Multifamily Housing Direct Loans', 'https://www.rd.usda.gov/programs-services/multi-family-housing-direct-loans', 'This program provides competitive financing for affordable multi-family rental housing for low-income, elderly, or disabled individuals and families in eligible rural areas.', 'Programs & Services', 'General', 'en'),
('Multifamily Housing Loan Guarantees', 'https://www.rd.usda.gov/programs-services/multi-family-housing-loan-guarantees', 'The program works with qualified private-sector lenders to provide financing to qualified borrowers to increase the supply of affordable rental housing for low- and moderate-income individuals and families in eligible rural areas and towns.', 'Programs & Services', 'General', 'en'),
('Off-Farm Labor Direct Loans & Grants', 'https://www.rd.usda.gov/programs-services/farm-labor-housing-direct-loans-grants', 'This program provides affordable financing to develop housing for year-round and migrant or seasonal domestic farm laborers.', 'Programs & Services', 'General', 'en'),
('On-Farm Labor Housing Loans', 'https://www.rd.usda.gov/programs-services/multifamily-housing-programs/farm-labor-housing-loans', 'This program provides affordable financing to develop or rehabilitate affordable rental housing for very-low income domestic, migrant, and seasonal farm laborers.', 'Programs & Services', 'General', 'en'),
('Multifamily Housing Preservation & Revitalization (MPR)', 'https://www.rd.usda.gov/programs-services/multifamily-housing-programs/multifamily-preservation-revitalization-loans-grants', 'This program restructures loans for existing Rural Rental Housing and Off-Farm Labor Housing projects to help improve and preserve the availability of safe affordable rental housing for low income residents.', 'Programs & Services', 'General', 'en'),
('Multifamily Housing Rental Assistance Program', 'https://www.rd.usda.gov/programs-services/multi-family-housing-rental-assistance', 'This program provides payments to owners of USDA-financed Rural Rental Housing or Farm Labor Housing projects on behalf of low-income tenants unable to pay their full rent.', 'Programs & Services', 'General', 'en'),
('Multifamily Tenant Voucher Program', 'https://www.rd.usda.gov/programs-services/multifamily-housing-programs/multifamily-tenant-voucher-program', 'This program provides vouchers to protect eligible tenants in Multifamily Direct Loan properties who may face hardship when a final loan payment is made on the property.', 'Programs & Services', 'General', 'en'),
('Multifamily Housing Nonprofit Transfer Technical Assistance Grants', 'https://www.rd.usda.gov/programs-services/multifamily-housing-programs/multi-family-housing-non-profit-transfer-technical-assistance-grants', 'USDA Rural Development awards grants to eligible nonprofit organizations and public housing authorities (PHAs) to provide technical assistance (TA) and other services to enable affordable housing preservation through the transfer of Multifamily Housing Direct Loan properties from current owners to nonprofits or PHAs.', 'Programs & Services', 'General', 'en'),
('Farm Labor Housing Technical Assistance Grants', 'https://www.rd.usda.gov/programs-services/multifamily-housing-programs/farm-labor-housing-technical-assistance-grants', 'USDA Rural Development awards grants to nonprofit organizations to provide technical assistance to applicants for Farm Labor Housing (FLH) loans and grants.', 'Programs & Services', 'General', 'en'),
('Section 521 Stand-Alone Rental Assistance', 'https://www.rd.usda.gov/programs-services/multifamily-housing-programs/section-521-stand-alone-rental-assistance', 'Decoupling Rental Assistance allows eligible USDA Rural Development Multifamily Housing (MFH) direct loan borrowers to continue receiving long-term rental assistance in exchange for agreeing to preserve and operate their multifamily property as affordable rural housing.', 'Programs & Services', 'General', 'en'),
('Well built, affordable housing is essential to the vitality of communities in rural America. Rural Development’s Single Family Housing Programs give families and individuals the opportunity to buy, bu', 'rural', 'https://eligibility.sc.egov.usda.gov/eligibility/welcomeAction.do', 'Programs & Services', 'General', 'en'),
('For the Single Family Housing Direct Home Loan Program, the Home Repair Loan and Grant program, and all nonprofit and Tribal programs, please  to locate your state or local office for assistance.', 'use this link', 'https://www.rd.usda.gov/about-rd/state-offices', 'Programs & Services', 'General', 'en'),
('Broadband Technical Assistance', 'https://www.rd.usda.gov/programs-services/telecommunications-programs/broadband-technical-assistance-program', 'BTA provides financial assistance through cooperative agreements to eligible entities to receive or deliver broadband technical assistance and training and supports the development and expansion of broadband service.', 'Programs & Services', 'General', 'en'),
('Community Connect Grants', 'https://www.rd.usda.gov/community-connect', 'The purpose of the Community Connect Program is to provide financial assistance in the form of grants to eligible applicants that will provide, on a “community -oriented connectivity” basis, broadband service that fosters economic growth and delivers enhanced educational, health care, and public safety benefits.', 'Programs & Services', 'General', 'en'),
('Distance Learning and Telemedicine Grants', 'https://www.rd.usda.gov/programs-services/telecommunications-programs/distance-learning-telemedicine-grants', 'The Distance Learning and Telemedicine program helps rural communities use the unique capabilities of telecommunications to connect to each other and to the world, overcoming the effects of remoteness and low population density.', 'Programs & Services', 'General', 'en'),
('Rural Broadband Loans, Loan/Grant Combinations, and Loan Guarantees', 'https://www.rd.usda.gov/programs-services/telecommunications-programs/rural-broadband-loans-loangrant-combinations-and-loan-guarantees', 'The Rural Broadband Loans, Loan/Grant Combinations, and Loan Guarantees (Farm Bill Broadband Program) furnishes loans and loan guarantees to provide funds for the costs of construction, improvement, or acquisition of facilities and equipment needed to provide service at the broadband lending speed in eligible rural areas', 'Programs & Services', 'General', 'en'),
('Telecommunications Infrastructure Loans and Loan Guarantees', 'https://www.rd.usda.gov/programs-services/telecommunications-programs/telecommunications-infrastructure-loans-loan-guarantees', 'This program provides financing for the construction, maintenance, improvement and expansion of telephone service and broadband in rural areas.', 'Programs & Services', 'General', 'en'),
('Calendar Year 2022 Disaster Water Grants Program', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/calendar-year-2022-disaster-water-grants-program', 'This program helps eligible communities handle expenses related to incidents (Presidentially declared disasters) that damaged water systems.', 'Programs & Services', 'General', 'en'),
('Calendar Year 2022 Disaster Circuit Rider Technical Assistance Grants Program', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/calendar-year-2022-disaster-circuit-rider-technical-assistance-grants-program', 'The Calendar Year (CY) 2022 Disaster Circuit Rider Technical Assistance (CRTA) Grants Program provides grant funds to qualified organizations for providing on-site technical assistance on a national basis to help eligible communities mitigate damage caused by CY 2022 Presidentially declared disasters.', 'Programs & Services', 'General', 'en'),
('Circuit Rider Program', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/circuit-rider-program-technical-assistance-rural-water-systems', 'This program provides technical assistance to rural water systems that are experiencing day-to-day operational, financial or managerial issues.', 'Programs & Services', 'General', 'en'),
('Emergency Community Water Assistance Grants', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/emergency-community-water-assistance-grants', 'This program helps eligible communities prepare, or recover from, an emergency that threatens the availability of safe, reliable drinking water.', 'Programs & Services', 'General', 'en'),
('Grants for Rural and Native Alaskan Villages', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/grants-rural-and-native-alaskan-villages', 'This program helps remote Alaskan villages provide safe, reliable drinking water and waste disposal systems for households and businesses.', 'Programs & Services', 'General', 'en'),
('Individual Water & Wastewater Grants', 'https://www.rd.usda.gov/programs-services/single-family-housing-programs/individual-water-wastewater-grants', 'This program provides funds to households in an area recognized as a Colonia before October 1, 1989.  Grant funds may be used to connect service lines to a residence, pay utility hook-up fees, install plumbing and related fixtures.', 'Programs & Services', 'General', 'en'),
('One Percent Loan Program for Distressed Communities', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/one-percent-loan-program-distressed-communities', 'This program provides funding for clean and reliable drinking water systems, sanitary sewage disposal, sanitary solid waste disposal, and storm water drainage to households and businesses in distressed communities located in eligible rural areas where the primary purpose of the loan is to upgrade existing facilities or construct new facilities required to meet applicable health or sanitary standards.', 'Programs & Services', 'General', 'en'),
('Rural Decentralized Water Systems Grant Program', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/rural-decentralized-water-systems-grant-program', 'This program helps qualified nonprofits and tribes create a revolving loan fund to increase access to clean, reliable water and septic systems for households in eligible rural areas.', 'Programs & Services', 'General', 'en'),
('Revolving Funds for Financing Water and Wastewater Projects (Revolving Fund Program)', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/revolving-funds-financing-water-and-wastewater-projects', 'This program helps qualified nonprofits create revolving loan funds that can provide financing to extend and improve water and waste disposal systems in rural areas.', 'Programs & Services', 'General', 'en'),
('SEARCH - Special Evaluation Assistance for Rural Communities and Households', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/search-special-evaluation-assistance-rural-communities-and-households-grant', 'This program helps very small, financially distressed rural communities with predevelopment feasibility studies, design and technical assistance on proposed water and waste disposal projects.', 'Programs & Services', 'General', 'en'),
('Solid Waste Management Grants', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/solid-waste-management-grants', 'This program reduces or eliminates pollution of water resources by providing funding for organizations that provide technical assistance or training to improve the planning and management of solid waste sites.', 'Programs & Services', 'General', 'en'),
('Technical Assistance and Training Program - Manufactured Homes', 'https://www.rd.usda.gov/programs-services/water-environmental-programs/technical-assistance-and-training-program-manufactured-homes', 'This grant program supports improved sustainability of water and waste services related to manufactured homes.', 'Programs & Services', 'General', 'en');